    The top of a post page: category, title, excerpt, the author line and an optional wide cover. Axes: layout (start, center), cover (show, hide), meta (full, short), tone.
    Props (p): id, post, labels, level, layout, cover, meta, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_post = ($p['post'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_level = ($p['level'] ?? 1)}
{var $v_layout = ($p['layout'] ?? 'start')}
{var $v_cover = ($p['cover'] ?? 'show')}
{var $v_meta = ($p['meta'] ?? 'full')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $f_6}
  {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_post, ['title']), 'ratio' => '21/9']])|noescape}
{/capture}
{capture $c_7}
  {capture $c_5}
    {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_post, ['author']), 'ratio' => '1/1', 'className' => ui_cnv(['size-10 shrink-0 rounded-full'])]])|noescape}
    {capture $c_1}
      {=ui_text(ui_get($v_post, ['author']))}
    {/capture}
    {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_1])|noescape}
    {capture $c_2}
      {=ui_text(ui_get($v_post, ['date']))}
    {/capture}
    {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_2])|noescape}
    {if ui_t(ui_eq($v_meta, 'full'))}
      {capture $c_3}
        {=ui_text(ui_tpl(ui_get($v_labels, ['minutes']), [ui_get($v_post, ['minutes'])]))}
      {/capture}
      {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_3])|noescape}
    {/if}
    {capture $c_4}
      {=ui_text(ui_get($v_post, ['category']))}
    {/capture}
    {=ui_include('blocks/pill.latte', ['p' => ['tone' => 'blue'], 'children' => $c_4])|noescape}
  {/capture}
  {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Align' => 'center', 'Justify' => ui_s((ui_t(ui_eq($v_layout, 'center')) ? 'center' : 'start')), 'Class' => 'flex-wrap', 'Attrs' => ui_attrs(['data-testid', 'post-meta'])], 'children' => $c_5])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => ui_get($v_post, ['title']), 'lead' => ui_get($v_post, ['excerpt']), 'heading' => ['level' => $v_level], 'align' => $v_layout, 'tone' => $v_tone, 'media' => ['show' => ui_eq($v_cover, 'show')], 'landmarkLabel' => $v_landmarkLabel, 'aside' => $f_6], 'children' => $c_7])|noescape}
